#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const files = {
  ".dockerignore": "node_modules\ndist\nprofile\nprofiles\ndownloads\n.git\n",
  ".env.example": "# Transport\nMCP_TRANSPORT=stdio\nMCP_HOST=0.0.0.0\nMCP_PORT=8080\nMCP_API_KEY=\n\n# Browser\nBROWSER_HEADLESS=true\nBROWSER_PROFILE_ROOT=/workspace/mcp-browser-agent/profiles\nBROWSER_DOWNLOAD_DIR=/workspace/mcp-browser-agent/downloads\nBROWSER_DEFAULT_TIMEOUT_MS=15000\nBROWSER_IDLE_WAIT_MS=1000\nBROWSER_MAX_SNAPSHOT_ITEMS=80\nBROWSER_MAX_TEXT_CHARS=5000\n\n# Access control\nALLOWED_ORIGINS=https://example.com,https://app.example.com\nDENIED_HOSTS=localhost,127.0.0.1,::1\nALLOWED_FILE_ROOTS=/workspace,/mnt\n\n# Optional\nMCP_STATE_DIR=/workspace/mcp-browser-agent/state\nLOG_LEVEL=info\n",
  "deploy/fly.toml": "app = \"mcp-browser-agent\"\nprimary_region = \"ams\"\n\n[build]\n  dockerfile = \"Dockerfile\"\n\n[env]\n  MCP_TRANSPORT = \"http\"\n  MCP_HOST = \"0.0.0.0\"\n  MCP_PORT = \"8080\"\n  BROWSER_HEADLESS = \"true\"\n  BROWSER_PROFILE_ROOT = \"/workspace/mcp-browser-agent/profiles\"\n  BROWSER_DOWNLOAD_DIR = \"/workspace/mcp-browser-agent/downloads\"\n  MCP_STATE_DIR = \"/workspace/mcp-browser-agent/state\"\n\n[http_service]\n  internal_port = 8080\n  force_https = true\n  auto_stop_machines = false\n  auto_start_machines = true\n  min_machines_running = 1\n",
  "deploy/railway.json": "{\n  \"$schema\": \"https://railway.app/railway.schema.json\",\n  \"build\": {\n    \"builder\": \"DOCKERFILE\"\n  },\n  \"deploy\": {\n    \"startCommand\": \"npm start\",\n    \"healthcheckPath\": \"/health\"\n  }\n}\n",
  "deploy/render.yaml": "services:\n  - type: web\n    name: mcp-browser-agent\n    env: docker\n    plan: starter\n    autoDeploy: true\n    healthCheckPath: /health\n    envVars:\n      - key: MCP_TRANSPORT\n        value: http\n      - key: MCP_HOST\n        value: 0.0.0.0\n      - key: MCP_PORT\n        value: 8080\n      - key: BROWSER_HEADLESS\n        value: true\n      - key: BROWSER_PROFILE_ROOT\n        value: /workspace/mcp-browser-agent/profiles\n      - key: BROWSER_DOWNLOAD_DIR\n        value: /workspace/mcp-browser-agent/downloads\n      - key: MCP_STATE_DIR\n        value: /workspace/mcp-browser-agent/state\n",
  "docker-compose.yml": "services:\n  mcp-browser-agent:\n    build: .\n    env_file:\n      - .env\n    ports:\n      - \"8080:8080\"\n    volumes:\n      - ./profiles:/workspace/mcp-browser-agent/profiles\n      - ./downloads:/workspace/mcp-browser-agent/downloads\n      - ./state:/workspace/mcp-browser-agent/state\n    restart: unless-stopped\n",
  "Dockerfile": "FROM mcr.microsoft.com/playwright:v1.54.2-noble\nWORKDIR /app\nCOPY package.json tsconfig.json .env.example ./\nRUN npm install\nCOPY src ./src\nRUN npm run build\nEXPOSE 8080\nCMD [\"npm\", \"start\"]\n",
  "docs/deploy.md": "# Deployment guide\n\n## Recommended setup\nUse Docker with the hosted SSE mode.\nPrefer persistent storage for browser profiles, downloads, and memory state.\n\n### Environment\nSet:\n- `MCP_TRANSPORT=http`\n- `MCP_HOST=0.0.0.0`\n- `MCP_PORT=8080`\n- `MCP_API_KEY=<strong secret>`\n- `BROWSER_HEADLESS=true`\n- `BROWSER_PROFILE_ROOT=/workspace/mcp-browser-agent/profiles`\n- `BROWSER_DOWNLOAD_DIR=/workspace/mcp-browser-agent/downloads`\n- `MCP_STATE_DIR=/workspace/mcp-browser-agent/state`\n- `ALLOWED_ORIGINS=<your allowed domains>`\n\n### Build\n```bash\ndocker build -t mcp-browser-agent .\n```\n\n### Run\n```bash\ndocker run --rm -p 8080:8080 --env-file .env mcp-browser-agent\n```\n\nIf your host supports volumes, mount these paths:\n- `/workspace/mcp-browser-agent/profiles`\n- `/workspace/mcp-browser-agent/downloads`\n- `/workspace/mcp-browser-agent/state`\n\n### ChatGPT app URL\nUse:\n- `https://YOUR_DOMAIN/sse/`\n\n## Render\n- Use `deploy/render.yaml` or the Dockerfile directly.\n- Add the same environment variables.\n- Make sure the service exposes port 8080.\n\n## Fly.io\n- Use `deploy/fly.toml`.\n- Set the secrets:\n  - `fly secrets set MCP_API_KEY=...`\n  - add any extra allowed origins or file roots\n\n## Railway\n- Use the Dockerfile.\n- Use `deploy/railway.json` as a guide.\n- Set `MCP_API_KEY` and the browser/storage paths.\n\n## Before go-live\n- Test `/health`\n- Test `/sse/`\n- Test one upload and one download\n- Test a profile switch\n- Test a logout/login flow\n- Test at least one Norwegian form flow\n",
  "docs/production-launch-checklist.md": "# Production launch checklist\n\n## Build\n- Verify TypeScript build locally.\n- Verify the MCP tool list looks correct.\n- Verify hosted SSE endpoint responds on `/health`.\n\n## Security\n- Set `MCP_API_KEY`.\n- Keep `ALLOWED_ORIGINS` restricted.\n- Keep `ALLOWED_FILE_ROOTS` restricted.\n- Keep confirmation gates on destructive tools.\n- Review request blocking rules.\n\n## Reliability\n- Test profile switching.\n- Test login and refresh recovery.\n- Test uploads, downloads, zip, unzip, and folder creation.\n- Test memory save/load.\n- Test Norwegian form handling on a real portal.\n\n## Operational\n- Set persistent storage for profiles, downloads, and state.\n- Turn on logs.\n- Add monitoring for crashes and timeouts.\n- Keep a manual fallback for identity, BankID, payment, and signature steps.\n",
  "package.json": "{\n  \"name\": \"mcp-browser-agent\",\n  \"version\": \"1.3.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"scripts\": {\n    \"dev\": \"tsx src/index.ts\",\n    \"dev:http\": \"MCP_TRANSPORT=http tsx src/index.ts\",\n    \"build\": \"tsc -p tsconfig.json\",\n    \"start\": \"node dist/index.js\",\n    \"start:http\": \"MCP_TRANSPORT=http node dist/index.js\",\n    \"check\": \"tsc -p tsconfig.json --noEmit\"\n  },\n  \"dependencies\": {\n    \"@modelcontextprotocol/sdk\": \"^1.17.1\",\n    \"dotenv\": \"^16.4.5\",\n    \"express\": \"^4.21.2\",\n    \"jszip\": \"^3.10.1\",\n    \"playwright\": \"^1.54.2\"\n  },\n  \"devDependencies\": {\n    \"@types/express\": \"^5.0.3\",\n    \"@types/node\": \"^22.15.30\",\n    \"tsx\": \"^4.20.3\",\n    \"typescript\": \"^5.8.3\"\n  }\n}\n",
  "Procfile": "web: npm start\n",
  "README.md": "# MCP Browser Agent\n\nProduction-oriented starter for a ChatGPT-compatible browser agent using MCP.\n\n## What it does\n- Keeps multiple persistent Playwright profiles\n- Exposes safe and risky browser tools over MCP\n- Supports request blocking rules\n- Saves browser downloads into sandbox folders\n- Supports cookie import/export\n- Supports uploads from approved local paths only\n- Uses allowlist and host-blocking rules\n- Returns structured page snapshots with refs\n- Returns screenshots as image content\n- Adds sandboxed file tools for reading/writing/archiving\n- Stores task memory in a local state file\n- Can run over stdio or hosted SSE for ChatGPT\n- Includes a helper file-browser page at `tools/file-browser.html`\n- Uses optional API-key auth in hosted mode\n- Includes deployment configs for Docker, Render, Fly.io, Railway, and Docker Compose\n\n## Tools\nProfiles and routing:\n- `browser.list_profiles`\n- `browser.create_profile`\n- `browser.use_profile`\n- `browser.current_profile`\n- `browser.current_page`\n- `browser.close_profile`\n- `browser.close_all_profiles`\n- `browser.request_rules`\n- `browser.set_request_rules`\n- `browser.clear_request_rules`\n\nBrowser control:\n- `browser.navigate`\n- `browser.snapshot`\n- `browser.extract`\n- `browser.wait`\n- `browser.screenshot`\n- `browser.downloads_list`\n- `browser.click`\n- `browser.type`\n- `browser.press`\n- `browser.select`\n- `browser.check`\n- `browser.uncheck`\n- `browser.submit`\n- `browser.open_tab`\n- `browser.close_tab`\n- `browser.close_others`\n- `browser.back`\n- `browser.forward`\n- `browser.reload`\n- `browser.hover`\n- `browser.scroll`\n- `browser.drag_drop`\n- `browser.upload_files`\n- `browser.upload_folder`\n- `browser.set_cookie`\n- `browser.import_cookies`\n- `browser.export_cookies`\n- `browser.clear_cookies`\n- `browser.clear_storage`\n- `browser.set_viewport`\n- `browser.evaluate`\n\nFile tools:\n- `files.list`\n- `files.tree`\n- `files.read_text`\n- `files.read_binary`\n- `files.write_text`\n- `files.write_binary`\n- `files.write_bundle`\n- `files.touch`\n- `files.mkdir`\n- `files.stat`\n- `files.preview`\n- `files.copy`\n- `files.move`\n- `files.delete`\n- `files.zip`\n- `files.unzip`\n\nMemory tools:\n- `memory.put`\n- `memory.get`\n- `memory.list`\n- `memory.delete`\n- `memory.clear`\n\n## Quick start\n\n```bash\nnpm install\nnpx playwright install\ncp .env.example .env\nnpm run dev\n```\n\n## Hosted SSE mode\n\n```bash\nMCP_TRANSPORT=http npm run dev:http\n# or build first and run:\nMCP_TRANSPORT=http npm run start:http\n```\n\nUse:\n- `http://YOUR_HOST:8080/sse/` as the MCP server URL\n- `MCP_API_KEY` for a simple access key if desired\n\n## Production run\n\n```bash\nnpm run build\nnpm start\n```\n\n## Docker Compose\n\n```bash\ndocker compose up -d --build\n```\n\n## Docker\n\n```bash\ndocker build -t mcp-browser-agent .\ndocker run --rm -it --env-file .env -p 8080:8080 mcp-browser-agent\n```\n\n## Deployment\n- Read [docs/deploy.md](docs/deploy.md)\n- See `deploy/render.yaml`, `deploy/fly.toml`, and `deploy/railway.json`\n- For production, use persistent storage for `profiles/`, `downloads/`, and `state/`\n\n## Safety notes\n- `browser.evaluate` is intentionally dangerous and runs arbitrary JavaScript in the page context.\n- Many state-changing tools require `confirm: true`.\n- `browser.upload_files` only accepts paths inside allowed roots.\n- File tools only work inside allowed roots, never across the entire machine.\n- Use `files.write_bundle` to create nested folder/file structures in one call.\n- Browser downloads are auto-saved to the sandbox download directory.\n- Keep confirmation gates for destructive tools when you host this publicly.\n",
  "references/norwegian-web-hints.md": "# Norwegian web hints for the main agent\n\nUse these when the browser agent must handle Norwegian sites.\n\n## High-value terms\n- fødselsnummer\n- d-nummer\n- organisasjonsnummer\n- vedlegg\n- postnummer\n- poststed\n- bekreft\n- send inn\n- lagre utkast\n- dokumentasjon\n- kvittering\n- saksnummer\n\n## Portal behavior\n- Dismiss consent banners first.\n- Expect multi-step forms.\n- Expect BankID or eID handoffs.\n- Expect fields that appear only after dropdown choices.\n- Expect attachments and confirmation summaries.\n",
  "src/auth/api-key.ts": "import { AppError } from '../errors.js';\nimport { config } from '../config.js';\n\nexport function assertAuthorized(headers: Record<string, unknown>) {\n  if (!config.apiKey) return true;\n  const auth = String(headers['authorization'] ?? headers['Authorization'] ?? '');\n  const apiKey = String(headers['x-api-key'] ?? headers['X-API-Key'] ?? '');\n  const bearer = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';\n  if (apiKey === config.apiKey || bearer === config.apiKey) return true;\n  throw new AppError('Unauthorized', 'UNAUTHORIZED');\n}\n",
  "src/browser/manager.ts": "import { chromium, type BrowserContext, type Page, type Request } from 'playwright';\nimport fs from 'node:fs/promises';\nimport path from 'node:path';\nimport { config } from '../config.js';\nimport { logger } from '../logger.js';\nimport { createSnapshot } from './snapshot.js';\nimport { preferredLocator } from './ref.js';\nimport { assertAllowedNavigation } from '../safety/policy.js';\nimport { AppError } from '../errors.js';\n\nexport type BrowserRequestRules = {\n  blockedDomains: string[];\n  blockedResourceTypes: string[];\n};\n\ntype LocatorInput = { ref?: string; selector?: string };\n\ntype SetCookieInput = {\n  name: string;\n  value: string;\n  url?: string;\n  domain?: string;\n  path?: string;\n  expires?: number;\n  httpOnly?: boolean;\n  secure?: boolean;\n  sameSite?: 'Strict' | 'Lax' | 'None';\n};\n\ntype DownloadRecord = {\n  filename: string;\n  savedAs: string;\n  url: string;\n  suggestedFilename: string;\n  failure?: string | null;\n  time: number;\n};\n\nfunction sanitizeFilename(input: string) {\n  return input.replace(/[^a-zA-Z0-9._-]+/g, '_').replace(/^_+/, '').slice(0, 160) || 'download.bin';\n}\n\nfunction matchesDomain(hostname: string, rule: string) {\n  const h = hostname.toLowerCase();\n  const r = rule.toLowerCase();\n  return h === r || h.endsWith(`.${r}`);\n}\n\nexport class BrowserManager {\n  private context: BrowserContext | null = null;\n  private activePage: Page | null = null;\n  private queue: Promise<unknown> = Promise.resolve();\n  private downloads: DownloadRecord[] = [];\n  private requestRules: BrowserRequestRules = { blockedDomains: [], blockedResourceTypes: [] };\n\n  constructor(\n    private readonly options: {\n      profileId: string;\n      profileDir: string;\n      downloadDir: string;\n    }\n  ) {}\n\n  get profileId() { return this.options.profileId; }\n  get profileDir() { return this.options.profileDir; }\n  get downloadDir() { return this.options.downloadDir; }\n\n  private shouldBlockRequest(request: Request) {\n    const url = request.url();\n    const resourceType = request.resourceType();\n    const host = (() => { try { return new URL(url).hostname; } catch { return ''; } })();\n    if (this.requestRules.blockedResourceTypes.includes(resourceType)) return true;\n    return this.requestRules.blockedDomains.some((rule) => host && matchesDomain(host, rule));\n  }\n\n  private async ensureDownloadDir() { await fs.mkdir(this.downloadDir, { recursive: true }); }\n\n  private attachPage(page: Page) {\n    page.setDefaultTimeout(config.defaultTimeoutMs);\n    page.setDefaultNavigationTimeout(config.defaultTimeoutMs);\n    page.on('console', (msg) => logger.debug('page-console', msg.type(), msg.text()));\n    page.on('pageerror', (err) => logger.warn('pageerror', err.message));\n    page.on('crash', () => logger.error('page-crash'));\n    page.on('close', () => { if (this.activePage === page) this.activePage = null; });\n    page.on('download', async (download) => {\n      try {\n        await this.ensureDownloadDir();\n        const suggested = sanitizeFilename(download.suggestedFilename());\n        const savedAs = path.join(this.downloadDir, `${Date.now()}-${Math.random().toString(16).slice(2)}-${suggested}`);\n        await download.saveAs(savedAs);\n        this.downloads.unshift({\n          filename: path.basename(savedAs),\n          savedAs,\n          url: download.url(),\n          suggestedFilename: download.suggestedFilename(),\n          failure: await download.failure(),\n          time: Date.now(),\n        });\n        this.downloads = this.downloads.slice(0, 50);\n      } catch (error) {\n        logger.warn('download-save-error', error instanceof Error ? error.message : String(error));\n      }\n    });\n    page.route('**/*', (route) => {\n      if (this.shouldBlockRequest(route.request())) {\n        logger.debug('blocked-request', route.request().resourceType(), route.request().url());\n        return route.abort('blockedbyclient');\n      }\n      return route.continue();\n    }).catch((err) => logger.warn('route-error', err instanceof Error ? err.message : String(err)));\n  }\n\n  async init() {\n    if (this.context) return;\n    await this.ensureDownloadDir();\n    this.context = await chromium.launchPersistentContext(this.options.profileDir, {\n      headless: config.headless,\n      ignoreHTTPSErrors: true,\n      viewport: { width: 1440, height: 1024 },\n      acceptDownloads: true,\n    });\n    this.context.setDefaultTimeout(config.defaultTimeoutMs);\n    this.context.setDefaultNavigationTimeout(config.defaultTimeoutMs);\n    this.context.on('page', (page) => this.attachPage(page));\n    const pages = this.context.pages();\n    this.activePage = pages.find((p) => !p.isClosed()) ?? (await this.context.newPage());\n    this.attachPage(this.activePage);\n  }\n\n  private async page() {\n    await this.init();\n    if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE');\n    if (!this.activePage || this.activePage.isClosed()) {\n      const pages = this.context.pages().filter((p) => !p.isClosed());\n      this.activePage = pages[0] ?? (await this.context.newPage());\n      this.attachPage(this.activePage);\n    }\n    return this.activePage;\n  }\n\n  private target(input: LocatorInput) { return preferredLocator(input.ref, input.selector); }\n\n  run<T>(fn: (page: Page) => Promise<T>) {\n    const job = this.queue.then(async () => fn(await this.page()));\n    this.queue = job.then(() => undefined, () => undefined);\n    return job;\n  }\n\n  async currentPage() {\n    return this.run(async (page) => ({ title: await page.title(), url: page.url(), profileId: this.profileId }));\n  }\n\n  async navigate(url: string, allowedOrigins: string[], deniedHosts: string[]) {\n    return this.run(async (page) => {\n      const parsed = assertAllowedNavigation(url, allowedOrigins, deniedHosts);\n      logger.info(`[${this.profileId}] navigate`, parsed.toString());\n      await page.goto(parsed.toString(), { waitUntil: 'domcontentloaded' });\n      await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined);\n      return createSnapshot(page);\n    });\n  }\n\n  async openTab(url?: string, allowedOrigins: string[] = [], deniedHosts: string[] = []) {\n    return this.run(async () => {\n      if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE');\n      const page = await this.context.newPage();\n      this.attachPage(page);\n      this.activePage = page;\n      if (url) {\n        const parsed = assertAllowedNavigation(url, allowedOrigins, deniedHosts);\n        await page.goto(parsed.toString(), { waitUntil: 'domcontentloaded' });\n        await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined);\n      }\n      return createSnapshot(page);\n    });\n  }\n\n  async closeTab() {\n    return this.run(async (page) => {\n      const pages = this.context?.pages().filter((p) => !p.isClosed()) ?? [];\n      if (pages.length <= 1) throw new AppError('Cannot close the last open tab', 'LAST_TAB');\n      const next = pages.find((p) => p !== page && !p.isClosed()) ?? null;\n      await page.close();\n      this.activePage = next ?? this.context?.pages().find((p) => !p.isClosed()) ?? null;\n      if (!this.activePage) throw new AppError('No tabs remain open', 'NO_TAB');\n      return createSnapshot(this.activePage);\n    });\n  }\n\n  async closeOthers() {\n    return this.run(async (page) => {\n      if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE');\n      const pages = this.context.pages().filter((p) => !p.isClosed());\n      for (const other of pages) { if (other !== page) await other.close(); }\n      this.activePage = page;\n      return createSnapshot(page);\n    });\n  }\n\n  async back() { return this.run(async (page) => { await page.goBack({ waitUntil: 'domcontentloaded' }).catch(() => null); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async forward() { return this.run(async (page) => { await page.goForward({ waitUntil: 'domcontentloaded' }).catch(() => null); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async reload() { return this.run(async (page) => { await page.reload({ waitUntil: 'domcontentloaded' }); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async click({ ref, selector }: LocatorInput) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().click({ timeout: config.defaultTimeoutMs }); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async type({ ref, selector, text }: LocatorInput & { text: string }) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().fill(text, { timeout: config.defaultTimeoutMs }); return createSnapshot(page); }); }\n  async press({ ref, selector, key }: LocatorInput & { key: string }) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().press(key, { timeout: config.defaultTimeoutMs }); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async select({ ref, selector, value, values }: LocatorInput & { value?: string; values?: string[] }) { return this.run(async (page) => { const target = this.target({ ref, selector }); const toSelect = values?.length ? values : value ? [value] : []; if (!toSelect.length) throw new AppError('Provide value or values', 'MISSING_VALUE'); await page.locator(target.value).first().selectOption(toSelect); return createSnapshot(page); }); }\n  async check({ ref, selector }: LocatorInput) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().check({ timeout: config.defaultTimeoutMs }); return createSnapshot(page); }); }\n  async uncheck({ ref, selector }: LocatorInput) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().uncheck({ timeout: config.defaultTimeoutMs }); return createSnapshot(page); }); }\n  async submit({ ref, selector }: LocatorInput) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().evaluate((el) => { const form = el instanceof HTMLFormElement ? el : el.closest('form'); if (!form) throw new Error('No form found'); form.requestSubmit(); }); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async hover({ ref, selector }: LocatorInput) { return this.run(async (page) => { const target = this.target({ ref, selector }); await page.locator(target.value).first().hover({ timeout: config.defaultTimeoutMs }); return createSnapshot(page); }); }\n  async scroll({ selector, dx = 0, dy = 800 }: { selector?: string; dx?: number; dy?: number }) { return this.run(async (page) => { if (selector) { await page.locator(selector).first().evaluate((el) => { (el as HTMLElement).scrollIntoView({ block: 'center', inline: 'center' }); }); } else { await page.mouse.wheel(dx, dy); } await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async dragDrop({ sourceRef, sourceSelector, targetRef, targetSelector }: { sourceRef?: string; sourceSelector?: string; targetRef?: string; targetSelector?: string }) { return this.run(async (page) => { const source = this.target({ ref: sourceRef, selector: sourceSelector }); const target = this.target({ ref: targetRef, selector: targetSelector }); await page.locator(source.value).first().dragTo(page.locator(target.value).first(), { timeout: config.defaultTimeoutMs }); await page.waitForLoadState('networkidle', { timeout: config.idleWaitMs }).catch(() => undefined); return createSnapshot(page); }); }\n  async uploadFiles({ ref, selector, files }: LocatorInput & { files: string[] }) { return this.run(async (page) => { if (!files.length) throw new AppError('No files provided', 'MISSING_FILES'); const target = this.target({ ref, selector }); await page.locator(target.value).first().setInputFiles(files, { timeout: config.defaultTimeoutMs }); return createSnapshot(page); }); }\n  async setCookie(cookies: SetCookieInput[]) { return this.run(async (page) => { if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE'); const currentUrl = page.url(); const defaultUrl = currentUrl.startsWith('http') ? currentUrl : undefined; const normalized = cookies.map((cookie) => ({ ...cookie, url: cookie.url ?? defaultUrl })).map((cookie) => { if (!cookie.url && !cookie.domain) throw new AppError(`Cookie ${cookie.name} needs url or domain`, 'COOKIE_SCOPE'); return cookie; }); await this.context.addCookies(normalized as Parameters<BrowserContext['addCookies']>[0]); return createSnapshot(page); }); }\n  async exportCookies() { return this.run(async () => { if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE'); return await this.context.cookies(); }); }\n  async importCookies(cookies: SetCookieInput[]) { return this.setCookie(cookies); }\n  async clearCookies() { return this.run(async () => { if (!this.context) throw new AppError('Browser not available', 'BROWSER_UNAVAILABLE'); await this.context.clearCookies(); return { ok: true }; }); }\n  async clearStorage() { return this.run(async (page) => { await page.evaluate(async () => { try { localStorage.clear(); } catch {} try { sessionStorage.clear(); } catch {} try { if ('databases' in indexedDB && typeof indexedDB.databases === 'function') { const dbs = await indexedDB.databases(); await Promise.all((dbs ?? []).map((db) => db.name ? indexedDB.deleteDatabase(db.name) : Promise.resolve())); } } catch {} }); return createSnapshot(page); }); }\n  async setViewport(width: number, height: number) { return this.run(async (page) => { await page.setViewportSize({ width, height }); return createSnapshot(page); }); }\n  async evaluate(code: string) { return this.run(async (page) => await page.evaluate((source) => eval(source), code)); }\n  async extract({ ref, selector, attribute }: LocatorInput & { attribute?: string }) { return this.run(async (page) => { const target = this.target({ ref, selector }); const locator = page.locator(target.value).first(); if (attribute) return await locator.getAttribute(attribute); return await locator.textContent(); }); }\n  async wait(input: { ms?: number; selector?: string; state?: 'attached' | 'detached' | 'visible' | 'hidden' }) { return this.run(async (page) => { if (typeof input.ms === 'number' && input.ms > 0) { await new Promise((resolve) => setTimeout(resolve, input.ms)); } else if (input.selector) { await page.waitForSelector(input.selector, { state: input.state ?? 'visible', timeout: config.defaultTimeoutMs }); } else { await page.waitForLoadState('networkidle', { timeout: config.defaultTimeoutMs }).catch(() => undefined); } return createSnapshot(page); }); }\n  async screenshot() { return this.run(async (page) => page.screenshot({ type: 'png', fullPage: false, encoding: 'base64' })); }\n  async listDownloads() { return this.downloads; }\n  async setRequestRules(rules: Partial<BrowserRequestRules>) { this.requestRules = { blockedDomains: rules.blockedDomains ?? this.requestRules.blockedDomains, blockedResourceTypes: rules.blockedResourceTypes ?? this.requestRules.blockedResourceTypes }; return this.requestRules; }\n  async clearRequestRules() { this.requestRules = { blockedDomains: [], blockedResourceTypes: [] }; return this.requestRules; }\n  getRequestRules() { return this.requestRules; }\n  async close() { if (this.context) { await this.context.close(); this.context = null; this.activePage = null; } }\n}\n",
  "src/browser/pool.ts": "import fs from 'node:fs/promises';\nimport path from 'node:path';\nimport { BrowserManager } from './manager.js';\n\nfunction sanitizeProfileId(id: string) {\n  return id.replace(/[^a-zA-Z0-9._-]+/g, '_').replace(/^_+/, '').slice(0, 80) || 'default';\n}\n\nexport class BrowserPool {\n  private managers = new Map<string, BrowserManager>();\n  private activeProfileId: string;\n\n  constructor(\n    private readonly options: {\n      profileRoot: string;\n      downloadRoot: string;\n    },\n    activeProfileId = 'default'\n  ) {\n    this.activeProfileId = sanitizeProfileId(activeProfileId);\n  }\n\n  private profileDir(profileId: string) {\n    return path.join(this.options.profileRoot, sanitizeProfileId(profileId));\n  }\n\n  private downloadDir(profileId: string) {\n    return path.join(this.options.downloadRoot, sanitizeProfileId(profileId));\n  }\n\n  private async ensureProfile(profileId: string) {\n    const id = sanitizeProfileId(profileId);\n    let manager = this.managers.get(id);\n    if (!manager) {\n      const profileDir = this.profileDir(id);\n      const downloadDir = this.downloadDir(id);\n      await fs.mkdir(profileDir, { recursive: true });\n      await fs.mkdir(downloadDir, { recursive: true });\n      manager = new BrowserManager({ profileId: id, profileDir, downloadDir });\n      this.managers.set(id, manager);\n    }\n    return manager;\n  }\n\n  async active() {\n    return this.ensureProfile(this.activeProfileId);\n  }\n\n  async useProfile(profileId: string) {\n    this.activeProfileId = sanitizeProfileId(profileId);\n    const manager = await this.active();\n    await manager.init();\n    return { activeProfileId: this.activeProfileId, profileDir: manager.profileDir, downloadDir: manager.downloadDir };\n  }\n\n  getActiveProfileId() {\n    return this.activeProfileId;\n  }\n\n  async listProfiles() {\n    await fs.mkdir(this.options.profileRoot, { recursive: true });\n    const entries = await fs.readdir(this.options.profileRoot, { withFileTypes: true }).catch(() => []);\n    const profiles = entries.filter((e) => e.isDirectory()).map((e) => e.name).sort();\n    if (!profiles.includes(this.activeProfileId)) profiles.unshift(this.activeProfileId);\n    return [...new Set(profiles)].map((id) => ({\n      id,\n      active: id === this.activeProfileId,\n      profileDir: this.profileDir(id),\n      downloadDir: this.downloadDir(id),\n    }));\n  }\n\n  async createProfile(profileId: string) {\n    const id = sanitizeProfileId(profileId);\n    await this.useProfile(id);\n    return { ok: true, profileId: id };\n  }\n\n  async closeProfile(profileId: string) {\n    const id = sanitizeProfileId(profileId);\n    const manager = this.managers.get(id);\n    if (manager) {\n      await manager.close();\n      this.managers.delete(id);\n    }\n    if (this.activeProfileId === id) this.activeProfileId = 'default';\n    return { ok: true, profileId: id };\n  }\n\n  async closeAllProfiles() {\n    for (const manager of this.managers.values()) {\n      await manager.close();\n    }\n    this.managers.clear();\n    this.activeProfileId = 'default';\n    return { ok: true };\n  }\n\n  async activeSnapshot() {\n    return (await this.active()).snapshot();\n  }\n\n  async navigate(url: string, allowedOrigins: string[], deniedHosts: string[]) {\n    return (await this.active()).navigate(url, allowedOrigins, deniedHosts);\n  }\n\n  async openTab(url?: string, allowedOrigins: string[] = [], deniedHosts: string[] = []) {\n    return (await this.active()).openTab(url, allowedOrigins, deniedHosts);\n  }\n\n  async closeTab() {\n    return (await this.active()).closeTab();\n  }\n\n  async closeOthers() {\n    return (await this.active()).closeOthers();\n  }\n\n  async back() { return (await this.active()).back(); }\n  async forward() { return (await this.active()).forward(); }\n  async reload() { return (await this.active()).reload(); }\n  async snapshot() { return (await this.active()).snapshot(); }\n  async currentPage() { return (await this.active()).currentPage(); }\n  async click(input: any) { return (await this.active()).click(input); }\n  async type(input: any) { return (await this.active()).type(input); }\n  async press(input: any) { return (await this.active()).press(input); }\n  async select(input: any) { return (await this.active()).select(input); }\n  async check(input: any) { return (await this.active()).check(input); }\n  async uncheck(input: any) { return (await this.active()).uncheck(input); }\n  async submit(input: any) { return (await this.active()).submit(input); }\n  async hover(input: any) { return (await this.active()).hover(input); }\n  async scroll(input: any) { return (await this.active()).scroll(input); }\n  async dragDrop(input: any) { return (await this.active()).dragDrop(input); }\n  async uploadFiles(input: any) { return (await this.active()).uploadFiles(input); }\n  async setCookie(input: any) { return (await this.active()).setCookie(input); }\n  async exportCookies() { return (await this.active()).exportCookies(); }\n  async importCookies(input: any) { return (await this.active()).importCookies(input); }\n  async clearCookies() { return (await this.active()).clearCookies(); }\n  async clearStorage() { return (await this.active()).clearStorage(); }\n  async setViewport(width: number, height: number) { return (await this.active()).setViewport(width, height); }\n  async evaluate(code: string) { return (await this.active()).evaluate(code); }\n  async extract(input: any) { return (await this.active()).extract(input); }\n  async wait(input: any) { return (await this.active()).wait(input); }\n  async screenshot() { return (await this.active()).screenshot(); }\n  async listDownloads() { return (await this.active()).listDownloads(); }\n  async setRequestRules(rules: any) { return (await this.active()).setRequestRules(rules); }\n  async clearRequestRules() { return (await this.active()).clearRequestRules(); }\n  async getRequestRules() { return (await this.active()).getRequestRules(); }\n\n  async close() {\n    await this.closeAllProfiles();\n  }\n}\n",
  "src/browser/ref.ts": "export function refSelector(ref: string) {\n  return `[data-mcp-ref=\"${ref.replace(/\"/g, '\\\\\"')}\"]`;\n}\n\nexport function preferredLocator(ref?: string, selector?: string) {\n  if (ref) return { kind: 'ref' as const, value: refSelector(ref) };\n  if (selector) return { kind: 'selector' as const, value: selector };\n  throw new Error('Provide ref or selector');\n}\n",
  "src/browser/snapshot.ts": "import type { Page } from 'playwright';\nimport { config } from '../config.js';\n\nexport type SnapshotElement = {\n  ref: string;\n  tag: string;\n  role: string;\n  name: string;\n  text: string;\n  href?: string | null;\n  value?: string | null;\n  placeholder?: string | null;\n  disabled?: boolean;\n  checked?: boolean;\n  selected?: boolean;\n};\n\nfunction cleanText(value: string) {\n  return value.replace(/\\s+/g, ' ').trim();\n}\n\nexport async function createSnapshot(page: Page) {\n  const data = await page.evaluate(({ maxItems, maxChars }) => {\n    const visible = (el: Element) => {\n      const rect = (el as HTMLElement).getBoundingClientRect();\n      const style = window.getComputedStyle(el);\n      return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;\n    };\n\n    const cleanup = () => document.querySelectorAll('[data-mcp-ref]').forEach((el) => el.removeAttribute('data-mcp-ref'));\n    cleanup();\n\n    const getLabel = (el: Element) => {\n      const htmlEl = el as HTMLElement;\n      const aria = htmlEl.getAttribute('aria-label');\n      if (aria) return aria.trim();\n      const title = htmlEl.getAttribute('title');\n      if (title) return title.trim();\n      const labelledBy = htmlEl.getAttribute('aria-labelledby');\n      if (labelledBy) {\n        const parts = labelledBy.split(/\\s+/).map((id) => document.getElementById(id)?.textContent?.trim()).filter(Boolean);\n        if (parts.length) return parts.join(' ');\n      }\n      if (htmlEl.id) {\n        const label = document.querySelector(`label[for=\"${CSS.escape(htmlEl.id)}\"]`)?.textContent?.trim();\n        if (label) return label;\n      }\n      const parentLabel = htmlEl.closest('label')?.textContent?.trim();\n      if (parentLabel) return parentLabel;\n      const text = htmlEl.innerText?.trim() || htmlEl.textContent?.trim() || '';\n      return text;\n    };\n\n    const inferRole = (el: Element) => {\n      const explicit = el.getAttribute('role');\n      if (explicit) return explicit;\n      const tag = el.tagName.toLowerCase();\n      if (tag === 'a') return 'link';\n      if (tag === 'button') return 'button';\n      if (['input', 'textarea', 'select'].includes(tag)) return 'textbox';\n      if (tag === 'summary') return 'button';\n      return tag;\n    };\n\n    const list = Array.from(document.querySelectorAll('button, a[href], input, textarea, select, summary, [role=\"button\"], [role=\"link\"], [contenteditable=\"true\"]'));\n    const items = [] as Array<Record<string, unknown>>;\n    let index = 0;\n    const seen = new Set<string>();\n\n    for (const el of list) {\n      if (items.length >= maxItems) break;\n      if (!(el instanceof HTMLElement)) continue;\n      if (!visible(el)) continue;\n\n      const role = inferRole(el);\n      const name = cleanText(getLabel(el));\n      const text = cleanText(el.innerText || el.textContent || '');\n      const signature = `${role}|${name}|${text}`;\n      if (!name && !text) continue;\n      if (seen.has(signature)) continue;\n      seen.add(signature);\n\n      const ref = `mcp-${++index}`;\n      el.setAttribute('data-mcp-ref', ref);\n      const tag = el.tagName.toLowerCase();\n      const htmlEl = el as HTMLInputElement & HTMLTextAreaElement & HTMLSelectElement;\n\n      items.push({\n        ref,\n        tag,\n        role,\n        name,\n        text: text.slice(0, 200),\n        href: el.getAttribute('href'),\n        value: 'value' in htmlEl ? htmlEl.value : null,\n        placeholder: el.getAttribute('placeholder'),\n        disabled: 'disabled' in htmlEl ? htmlEl.disabled : false,\n        checked: 'checked' in htmlEl ? htmlEl.checked : false,\n        selected: 'selected' in htmlEl ? htmlEl.selected : false,\n      });\n    }\n\n    return {\n      items,\n      bodyText: cleanText(document.body?.innerText || '').slice(0, maxChars),\n      readyState: document.readyState,\n    };\n  }, { maxItems: config.maxSnapshotItems, maxChars: config.maxTextChars });\n\n  return {\n    title: await page.title(),\n    url: page.url(),\n    readyState: data.readyState,\n    itemCount: data.items.length,\n    text: data.bodyText,\n    items: data.items as SnapshotElement[],\n  };\n}\n",
  "src/config.ts": "import 'dotenv/config';\n\nfunction parseList(value: string | undefined) {\n  return (value ?? '')\n    .split(',')\n    .map((s) => s.trim())\n    .filter(Boolean);\n}\n\nfunction parseNumber(value: string | undefined, fallback: number) {\n  const n = Number(value);\n  return Number.isFinite(n) && n > 0 ? n : fallback;\n}\n\nexport const config = {\n  appName: 'mcp-browser-agent',\n  version: '1.3.0',\n  transport: process.env.MCP_TRANSPORT ?? 'stdio',\n  host: process.env.MCP_HOST ?? '0.0.0.0',\n  port: parseNumber(process.env.MCP_PORT, 8080),\n  apiKey: process.env.MCP_API_KEY ?? '',\n  headless: process.env.BROWSER_HEADLESS !== 'false',\n  profileRoot: process.env.BROWSER_PROFILE_ROOT ?? '/workspace/mcp-browser-agent/profiles',\n  downloadRoot: process.env.BROWSER_DOWNLOAD_DIR ?? '/workspace/mcp-browser-agent/downloads',\n  stateDir: process.env.MCP_STATE_DIR ?? '/workspace/mcp-browser-agent/state',\n  defaultTimeoutMs: parseNumber(process.env.BROWSER_DEFAULT_TIMEOUT_MS, 15000),\n  idleWaitMs: parseNumber(process.env.BROWSER_IDLE_WAIT_MS, 1000),\n  maxSnapshotItems: parseNumber(process.env.BROWSER_MAX_SNAPSHOT_ITEMS, 80),\n  maxTextChars: parseNumber(process.env.BROWSER_MAX_TEXT_CHARS, 5000),\n  allowedOrigins: parseList(process.env.ALLOWED_ORIGINS),\n  deniedHosts: parseList(process.env.DENIED_HOSTS),\n  allowedFileRoots: parseList(process.env.ALLOWED_FILE_ROOTS || '/workspace,/mnt'),\n  logLevel: process.env.LOG_LEVEL ?? 'info',\n};\n",
  "src/errors.ts": "export class AppError extends Error {\n  constructor(\n    message: string,\n    public readonly code = 'APP_ERROR'\n  ) {\n    super(message);\n    this.name = 'AppError';\n  }\n}\n",
  "src/files/policy.ts": "import path from 'node:path';\nimport { AppError } from '../errors.js';\n\nfunction normalize(p: string) {\n  return path.resolve(p);\n}\n\nexport function assertPathAllowed(inputPath: string, allowedRoots: string[]) {\n  const resolved = normalize(inputPath);\n  const ok = allowedRoots.some((root) => {\n    const base = normalize(root);\n    return resolved === base || resolved.startsWith(base.endsWith(path.sep) ? base : base + path.sep);\n  });\n  if (!ok) {\n    throw new AppError(`Path not allowed: ${inputPath}`, 'PATH_NOT_ALLOWED');\n  }\n  return resolved;\n}\n\nexport function assertPathsAllowed(paths: string[], allowedRoots: string[]) {\n  return paths.map((p) => assertPathAllowed(p, allowedRoots));\n}\n",
  "src/files/service.ts": "import fs from 'node:fs/promises';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\nimport JSZip from 'jszip';\nimport { AppError } from '../errors.js';\nimport { assertPathAllowed } from './policy.js';\n\nexport type FileEntry = {\n  name: string;\n  path: string;\n  type: 'file' | 'directory' | 'other';\n  size: number;\n  mtimeMs: number;\n};\n\nexport type FileTreeNode = {\n  name: string;\n  path: string;\n  type: 'file' | 'directory' | 'other';\n  size?: number;\n  mtimeMs?: number;\n  children?: FileTreeNode[];\n};\n\nfunction isTextFile(filePath: string) {\n  const ext = path.extname(filePath).toLowerCase();\n  return [\n    '.txt', '.md', '.json', '.csv', '.ts', '.js', '.jsx', '.tsx', '.html', '.css', '.scss', '.yml', '.yaml', '.xml', '.log', '.env', '.ini', '.toml', '.sql', '.sh', '.py', '.rb', '.go', '.java', '.php'\n  ].includes(ext);\n}\n\nasync function ensureParent(filePath: string) {\n  await fs.mkdir(path.dirname(filePath), { recursive: true });\n}\n\nasync function walk(dir: string, out: Array<{ abs: string; rel: string }>, prefix = '') {\n  const entries = await fs.readdir(dir, { withFileTypes: true });\n  for (const entry of entries) {\n    const abs = path.join(dir, entry.name);\n    const rel = prefix ? path.join(prefix, entry.name) : entry.name;\n    if (entry.isDirectory()) {\n      out.push({ abs, rel: rel + path.sep });\n      await walk(abs, out, rel);\n    } else {\n      out.push({ abs, rel });\n    }\n  }\n}\n\nexport class FileService {\n  constructor(private readonly allowedRoots: string[]) {}\n\n  resolve(inputPath: string) {\n    return assertPathAllowed(inputPath, this.allowedRoots);\n  }\n\n  async stat(inputPath: string) {\n    const filePath = this.resolve(inputPath);\n    const info = await fs.stat(filePath);\n    return {\n      path: filePath,\n      name: path.basename(filePath),\n      type: info.isDirectory() ? 'directory' : info.isFile() ? 'file' : 'other',\n      size: info.size,\n      mtimeMs: info.mtimeMs,\n    };\n  }\n\n  async list(inputPath: string) {\n    const dir = this.resolve(inputPath);\n    const entries = await fs.readdir(dir, { withFileTypes: true });\n    const results: FileEntry[] = [];\n    for (const entry of entries) {\n      const abs = path.join(dir, entry.name);\n      const info = await fs.stat(abs);\n      results.push({\n        name: entry.name,\n        path: abs,\n        type: entry.isDirectory() ? 'directory' : entry.isFile() ? 'file' : 'other',\n        size: info.size,\n        mtimeMs: info.mtimeMs,\n      });\n    }\n    return results.sort((a, b) => a.name.localeCompare(b.name));\n  }\n\n  async tree(inputPath: string, depth = 8, maxEntries = 1000) {\n    const root = this.resolve(inputPath);\n    let seen = 0;\n\n    const build = async (current: string, remainingDepth: number): Promise<FileTreeNode> => {\n      const info = await fs.stat(current);\n      const node: FileTreeNode = {\n        name: path.basename(current) || current,\n        path: current,\n        type: info.isDirectory() ? 'directory' : info.isFile() ? 'file' : 'other',\n        size: info.size,\n        mtimeMs: info.mtimeMs,\n      };\n\n      if (!info.isDirectory() || remainingDepth <= 0 || seen >= maxEntries) return node;\n      const entries = await fs.readdir(current, { withFileTypes: true });\n      node.children = [];\n      for (const entry of entries) {\n        if (seen >= maxEntries) break;\n        seen += 1;\n        node.children.push(await build(path.join(current, entry.name), remainingDepth - 1));\n      }\n      return node;\n    };\n\n    return build(root, depth);\n  }\n\n  async collectFiles(inputPath: string, recursive = true) {\n    const root = this.resolve(inputPath);\n    const info = await fs.stat(root);\n    if (info.isFile()) return [root];\n    if (!info.isDirectory()) return [];\n\n    const out: Array<{ abs: string; rel: string }> = [];\n    if (recursive) {\n      await walk(root, out);\n      return out.filter((item) => !item.rel.endsWith(path.sep)).map((item) => item.abs);\n    }\n\n    const entries = await fs.readdir(root, { withFileTypes: true });\n    return entries.filter((e) => e.isFile()).map((e) => path.join(root, e.name));\n  }\n\n  async readText(inputPath: string, maxBytes = 1024 * 1024) {\n    const filePath = this.resolve(inputPath);\n    const buffer = await fs.readFile(filePath);\n    if (buffer.length > maxBytes) {\n      return buffer.subarray(0, maxBytes).toString('utf8') + '\\n…[truncated]';\n    }\n    return buffer.toString('utf8');\n  }\n\n  async readBinary(inputPath: string, maxBytes = 25 * 1024 * 1024) {\n    const filePath = this.resolve(inputPath);\n    const buffer = await fs.readFile(filePath);\n    if (buffer.length > maxBytes) {\n      throw new AppError(`File too large to read as base64: ${inputPath}`, 'FILE_TOO_LARGE');\n    }\n    return {\n      path: filePath,\n      name: path.basename(filePath),\n      size: buffer.length,\n      base64: buffer.toString('base64'),\n      sha256: crypto.createHash('sha256').update(buffer).digest('hex'),\n    };\n  }\n\n  async writeText(inputPath: string, content: string) {\n    const filePath = this.resolve(inputPath);\n    await ensureParent(filePath);\n    await fs.writeFile(filePath, content, 'utf8');\n    return this.stat(filePath);\n  }\n\n  async writeBinary(inputPath: string, base64: string) {\n    const filePath = this.resolve(inputPath);\n    const buffer = Buffer.from(base64, 'base64');\n    await ensureParent(filePath);\n    await fs.writeFile(filePath, buffer);\n    return this.stat(filePath);\n  }\n\n  async writeBundle(entries: Array<{ path: string; text?: string; base64?: string; directory?: boolean }>) {\n    const results: Array<Record<string, unknown>> = [];\n    for (const entry of entries) {\n      const fullPath = this.resolve(entry.path);\n      if (entry.directory || entry.path.endsWith('/')) {\n        await fs.mkdir(fullPath, { recursive: true });\n        results.push(await this.stat(fullPath));\n        continue;\n      }\n      await ensureParent(fullPath);\n      if (typeof entry.base64 === 'string') {\n        await fs.writeFile(fullPath, Buffer.from(entry.base64, 'base64'));\n      } else {\n        await fs.writeFile(fullPath, entry.text ?? '', 'utf8');\n      }\n      results.push(await this.stat(fullPath));\n    }\n    return { ok: true, written: results };\n  }\n\n  async touch(inputPath: string) {\n    const filePath = this.resolve(inputPath);\n    await ensureParent(filePath);\n    await fs.writeFile(filePath, '', { flag: 'a' });\n    return this.stat(filePath);\n  }\n\n  async mkdir(inputPath: string) {\n    const dir = this.resolve(inputPath);\n    await fs.mkdir(dir, { recursive: true });\n    return this.stat(dir);\n  }\n\n  async remove(inputPath: string) {\n    const filePath = this.resolve(inputPath);\n    await fs.rm(filePath, { recursive: true, force: true });\n    return { ok: true, path: filePath };\n  }\n\n  async copy(source: string, destination: string) {\n    const src = this.resolve(source);\n    const dst = this.resolve(destination);\n    await ensureParent(dst);\n    await fs.cp(src, dst, { recursive: true, force: true, errorOnExist: false });\n    return this.stat(dst);\n  }\n\n  async move(source: string, destination: string) {\n    const src = this.resolve(source);\n    const dst = this.resolve(destination);\n    await ensureParent(dst);\n    await fs.rename(src, dst);\n    return this.stat(dst);\n  }\n\n  async preview(inputPath: string) {\n    const filePath = this.resolve(inputPath);\n    const info = await fs.stat(filePath);\n    const base = {\n      path: filePath,\n      name: path.basename(filePath),\n      type: info.isFile() ? 'file' : info.isDirectory() ? 'directory' : 'other',\n      size: info.size,\n    };\n\n    if (!info.isFile()) return base;\n\n    const buffer = await fs.readFile(filePath);\n    if (isTextFile(filePath)) {\n      return { ...base, text: buffer.toString('utf8').slice(0, 20000) };\n    }\n\n    return {\n      ...base,\n      sha256: crypto.createHash('sha256').update(buffer).digest('hex'),\n    };\n  }\n\n  async zip(sources: string[], destinationZip: string) {\n    const zipPath = this.resolve(destinationZip);\n    const zip = new JSZip();\n    for (const source of sources) {\n      const abs = this.resolve(source);\n      const info = await fs.stat(abs);\n      if (info.isDirectory()) {\n        const collected: Array<{ abs: string; rel: string }> = [];\n        await walk(abs, collected);\n        for (const item of collected) {\n          if (item.rel.endsWith(path.sep)) continue;\n          zip.file(path.join(path.basename(abs), item.rel), await fs.readFile(item.abs));\n        }\n      } else {\n        zip.file(path.basename(abs), await fs.readFile(abs));\n      }\n    }\n    const buffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });\n    await ensureParent(zipPath);\n    await fs.writeFile(zipPath, buffer);\n    return this.stat(zipPath);\n  }\n\n  async unzip(zipSource: string, destinationDir: string) {\n    const src = this.resolve(zipSource);\n    const dst = this.resolve(destinationDir);\n    const buffer = await fs.readFile(src);\n    const zip = await JSZip.loadAsync(buffer);\n    await fs.mkdir(dst, { recursive: true });\n\n    const written: string[] = [];\n    for (const [name, entry] of Object.entries(zip.files)) {\n      const outPath = path.resolve(dst, name);\n      if (!outPath.startsWith(dst)) throw new AppError('Archive contains unsafe path', 'ARCHIVE_PATH');\n      if (entry.dir) {\n        await fs.mkdir(outPath, { recursive: true });\n      } else {\n        await ensureParent(outPath);\n        const data = await entry.async('nodebuffer');\n        await fs.writeFile(outPath, data);\n        written.push(outPath);\n      }\n    }\n    return { ok: true, extracted: written.length, destination: dst };\n  }\n}\n",
  "src/http.ts": "import express from 'express';\nimport { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';\nimport { createMcpServer } from './server.js';\nimport type { BrowserPool } from './browser/pool.js';\nimport type { FileService } from './files/service.js';\nimport { config } from './config.js';\nimport { logger } from './logger.js';\nimport { assertAuthorized } from './auth/api-key.js';\n\nexport async function startHttpServer(runtime: { browser: BrowserPool; files: FileService }) {\n  const app = express();\n  app.use(express.json({ limit: '25mb' }));\n\n  const transports = new Map<string, SSEServerTransport>();\n\n  app.get('/health', (_req, res) => {\n    res.json({ ok: true, transport: 'sse', version: config.version });\n  });\n\n  const requireAuth = (req: express.Request, res: express.Response) => {\n    try {\n      assertAuthorized(req.headers as Record<string, unknown>);\n      return true;\n    } catch {\n      res.status(401).json({ error: 'Unauthorized' });\n      return false;\n    }\n  };\n\n  const openSse = async (req: express.Request, res: express.Response) => {\n    if (!requireAuth(req, res)) return;\n    const transport = new SSEServerTransport('/messages', res) as any;\n    transports.set(transport.sessionId, transport);\n    res.on('close', () => {\n      transports.delete(transport.sessionId);\n    });\n    const { server: mcpServer } = await createMcpServer(runtime as any);\n    await mcpServer.connect(transport);\n  };\n\n  app.get('/sse', openSse);\n  app.get('/sse/', openSse);\n\n  const handleMessages = async (req: express.Request, res: express.Response) => {\n    if (!requireAuth(req, res)) return;\n    const sessionId = String(req.query.sessionId ?? req.header('x-session-id') ?? req.header('mcp-session-id') ?? '');\n    const transport = transports.get(sessionId);\n    if (!transport) {\n      res.status(404).json({ error: 'Unknown session' });\n      return;\n    }\n    await transport.handlePostMessage(req, res);\n  };\n\n  app.post('/messages', handleMessages);\n  app.post('/messages/', handleMessages);\n\n  return new Promise<{ close: () => Promise<void> }>((resolve) => {\n    const serverInstance = app.listen(config.port, config.host, () => {\n      logger.info(`HTTP SSE server listening on http://${config.host}:${config.port}/sse/`);\n      resolve({\n        close: async () => {\n          await runtime.browser.close();\n          await new Promise<void>((done) => serverInstance.close(() => done()));\n        },\n      });\n    });\n  });\n}\n",
  "src/index.ts": "import { startStdioServer } from './server.js';\nimport { startHttpServer } from './http.js';\nimport { createRuntime } from './runtime.js';\nimport { config } from './config.js';\nimport { logger } from './logger.js';\n\nif (config.transport === 'http') {\n  const runtime = createRuntime();\n  const host = await startHttpServer(runtime);\n  logger.info('HTTP transport ready');\n\n  async function shutdown(signal: string) {\n    logger.info(`Shutting down on ${signal}`);\n    await host.close();\n    process.exit(0);\n  }\n\n  process.on('SIGINT', () => { void shutdown('SIGINT'); });\n  process.on('SIGTERM', () => { void shutdown('SIGTERM'); });\n} else {\n  const runtime = await startStdioServer();\n  logger.info('STDIO transport ready');\n\n  async function shutdown(signal: string) {\n    logger.info(`Shutting down on ${signal}`);\n    await runtime.close();\n    process.exit(0);\n  }\n\n  process.on('SIGINT', () => { void shutdown('SIGINT'); });\n  process.on('SIGTERM', () => { void shutdown('SIGTERM'); });\n}\n",
  "src/logger.ts": "import { config } from './config.js';\n\ntype Level = 'debug' | 'info' | 'warn' | 'error';\nconst order: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };\nconst current = order[(config.logLevel as Level) ?? 'info'] ?? order.info;\n\nfunction write(level: Level, args: unknown[]) {\n  if (order[level] < current) return;\n  const prefix = `[${new Date().toISOString()}] [${level}] [${config.appName}]`;\n  console.log(prefix, ...args);\n}\n\nexport const logger = {\n  debug: (...args: unknown[]) => write('debug', args),\n  info: (...args: unknown[]) => write('info', args),\n  warn: (...args: unknown[]) => write('warn', args),\n  error: (...args: unknown[]) => write('error', args),\n};\n",
  "src/mcp/tool-definitions.ts": "export const toolDefinitions = [\n  { name: 'browser.list_profiles', description: 'List saved browser profiles.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.create_profile', description: 'Create or activate a browser profile.', inputSchema: { type: 'object', properties: { profileId: { type: 'string' } }, required: ['profileId'], additionalProperties: false } },\n  { name: 'browser.use_profile', description: 'Switch to a browser profile.', inputSchema: { type: 'object', properties: { profileId: { type: 'string' } }, required: ['profileId'], additionalProperties: false } },\n  { name: 'browser.current_profile', description: 'Return the active browser profile.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.current_page', description: 'Return the active page title and URL.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.close_profile', description: 'Close a browser profile session.', inputSchema: { type: 'object', properties: { profileId: { type: 'string' } }, required: ['profileId'], additionalProperties: false } },\n  { name: 'browser.close_all_profiles', description: 'Close every browser profile session.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.request_rules', description: 'Inspect the current request blocking rules.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.set_request_rules', description: 'Set request blocking rules for the active browser profile.', inputSchema: { type: 'object', properties: { blockedDomains: { type: 'array', items: { type: 'string' } }, blockedResourceTypes: { type: 'array', items: { type: 'string' } } }, additionalProperties: false } },\n  { name: 'browser.clear_request_rules', description: 'Clear request blocking rules.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.navigate', description: 'Navigate the current browser session to a URL. Navigation is restricted by allowlist and host policy.', inputSchema: { type: 'object', properties: { url: { type: 'string' } }, required: ['url'], additionalProperties: false } },\n  { name: 'browser.open_tab', description: 'Open a new browser tab, optionally navigating to a URL.', inputSchema: { type: 'object', properties: { url: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.close_tab', description: 'Close the current browser tab.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.close_others', description: 'Close every tab except the current one.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.back', description: 'Go back in browser history.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.forward', description: 'Go forward in browser history.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.reload', description: 'Reload the current page.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.snapshot', description: 'Capture the current page state, visible interactive elements, and a text excerpt.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.click', description: 'Click an element by ref from snapshot or by CSS selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.type', description: 'Fill an input by ref from snapshot or by CSS selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, text: { type: 'string' } }, required: ['text'], additionalProperties: false } },\n  { name: 'browser.press', description: 'Press a key on an element by ref or selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, key: { type: 'string' } }, required: ['key'], additionalProperties: false } },\n  { name: 'browser.select', description: 'Select option(s) in a select element.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, value: { type: 'string' }, values: { type: 'array', items: { type: 'string' } } }, additionalProperties: false } },\n  { name: 'browser.check', description: 'Check a checkbox or radio by ref or selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.uncheck', description: 'Uncheck a checkbox by ref or selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.submit', description: 'Submit the nearest form around an element or selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.hover', description: 'Hover an element by ref or selector.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.scroll', description: 'Scroll the page or an element.', inputSchema: { type: 'object', properties: { selector: { type: 'string' }, dx: { type: 'number' }, dy: { type: 'number' } }, additionalProperties: false } },\n  { name: 'browser.drag_drop', description: 'Drag from one element to another.', inputSchema: { type: 'object', properties: { sourceRef: { type: 'string' }, sourceSelector: { type: 'string' }, targetRef: { type: 'string' }, targetSelector: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.upload_files', description: 'Upload one or more files into a file input.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, files: { type: 'array', items: { type: 'string' } } }, required: ['files'], additionalProperties: false } },\n  { name: 'browser.upload_folder', description: 'Upload all files in a folder recursively into a file input.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, path: { type: 'string' }, recursive: { type: 'boolean' } }, required: ['path'], additionalProperties: false } },\n  { name: 'browser.set_cookie', description: 'Add cookies to the current browser context.', inputSchema: { type: 'object', properties: { cookies: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, value: { type: 'string' }, url: { type: 'string' }, domain: { type: 'string' }, path: { type: 'string' }, expires: { type: 'number' }, httpOnly: { type: 'boolean' }, secure: { type: 'boolean' }, sameSite: { type: 'string', enum: ['Strict', 'Lax', 'None'] } }, required: ['name', 'value'], additionalProperties: false } } }, required: ['cookies'], additionalProperties: false } },\n  { name: 'browser.import_cookies', description: 'Import cookies from JSON or an allowed file path.', inputSchema: { type: 'object', properties: { path: { type: 'string' }, cookies: { type: 'array', items: { type: 'object' } } }, additionalProperties: false } },\n  { name: 'browser.export_cookies', description: 'Export cookies as JSON, optionally to an allowed file path.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.clear_cookies', description: 'Clear all cookies for the current browser context.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.clear_storage', description: 'Clear localStorage, sessionStorage, and IndexedDB for the current origin.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.set_viewport', description: 'Change the viewport size for the active tab.', inputSchema: { type: 'object', properties: { width: { type: 'number' }, height: { type: 'number' } }, required: ['width', 'height'], additionalProperties: false } },\n  { name: 'browser.evaluate', description: 'Execute arbitrary JavaScript in the page context and return the result.', inputSchema: { type: 'object', properties: { code: { type: 'string' } }, required: ['code'], additionalProperties: false } },\n  { name: 'browser.downloads_list', description: 'List browser-managed downloads saved to the sandbox download folder.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'browser.extract', description: 'Read text or an attribute from an element.', inputSchema: { type: 'object', properties: { ref: { type: 'string' }, selector: { type: 'string' }, attribute: { type: 'string' } }, additionalProperties: false } },\n  { name: 'browser.wait', description: 'Wait for a selector, load state, or fixed delay.', inputSchema: { type: 'object', properties: { ms: { type: 'number' }, selector: { type: 'string' }, state: { type: 'string', enum: ['attached', 'detached', 'visible', 'hidden'] } }, additionalProperties: false } },\n  { name: 'browser.screenshot', description: 'Capture a PNG screenshot of the current page.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n  { name: 'files.list', description: 'List a sandboxed directory under allowed roots.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.tree', description: 'Return a recursive tree for a sandboxed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' }, depth: { type: 'number' }, maxEntries: { type: 'number' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.read_text', description: 'Read a text file from an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.read_binary', description: 'Read any file as base64 from an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.write_text', description: 'Write text to a file in an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'], additionalProperties: false } },\n  { name: 'files.write_binary', description: 'Write any file from base64 to an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' }, base64: { type: 'string' } }, required: ['path', 'base64'], additionalProperties: false } },\n  { name: 'files.write_bundle', description: 'Create folders and files from a structured bundle.', inputSchema: { type: 'object', properties: { entries: { type: 'array', items: { type: 'object' } } }, required: ['entries'], additionalProperties: false } },\n  { name: 'files.touch', description: 'Create an empty file in an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.mkdir', description: 'Create a directory in an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.stat', description: 'Inspect a file or directory in an allowed folder.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.preview', description: 'Preview a common text file or show a hash for binary files.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.copy', description: 'Copy a file or directory inside allowed roots.', inputSchema: { type: 'object', properties: { source: { type: 'string' }, destination: { type: 'string' } }, required: ['source', 'destination'], additionalProperties: false } },\n  { name: 'files.move', description: 'Move a file or directory inside allowed roots.', inputSchema: { type: 'object', properties: { source: { type: 'string' }, destination: { type: 'string' } }, required: ['source', 'destination'], additionalProperties: false } },\n  { name: 'files.delete', description: 'Delete a file or directory inside allowed roots.', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'], additionalProperties: false } },\n  { name: 'files.zip', description: 'Create a zip archive from files or folders inside allowed roots.', inputSchema: { type: 'object', properties: { sources: { type: 'array', items: { type: 'string' } }, destination: { type: 'string' } }, required: ['sources', 'destination'], additionalProperties: false } },\n  { name: 'files.unzip', description: 'Extract a zip archive into a directory inside allowed roots.', inputSchema: { type: 'object', properties: { source: { type: 'string' }, destination: { type: 'string' } }, required: ['source', 'destination'], additionalProperties: false } },\n  { name: 'memory.put', description: 'Store a task note or state item.', inputSchema: { type: 'object', properties: { key: { type: 'string' }, value: { anyOf: [{ type: 'string' }, { type: 'number' }, { type: 'boolean' }, { type: 'object' }, { type: 'array' }, { type: 'null' }] }, tags: { type: 'array', items: { type: 'string' } } }, required: ['key', 'value'], additionalProperties: false } },\n  { name: 'memory.get', description: 'Read one task memory item.', inputSchema: { type: 'object', properties: { key: { type: 'string' } }, required: ['key'], additionalProperties: false } },\n  { name: 'memory.list', description: 'List memory items.', inputSchema: { type: 'object', properties: { prefix: { type: 'string' } }, additionalProperties: false } },\n  { name: 'memory.delete', description: 'Delete a memory item.', inputSchema: { type: 'object', properties: { key: { type: 'string' } }, required: ['key'], additionalProperties: false } },\n  { name: 'memory.clear', description: 'Clear all memory items.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },\n] as const;\n",
  "src/memory/store.ts": "import fs from 'node:fs/promises';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\n\nexport type MemoryItem = {\n  id: string;\n  key: string;\n  value: unknown;\n  tags?: string[];\n  createdAt: string;\n  updatedAt: string;\n};\n\nexport class MemoryStore {\n  private items = new Map<string, MemoryItem>();\n\n  constructor(private readonly filePath: string) {}\n\n  async load() {\n    await fs.mkdir(path.dirname(this.filePath), { recursive: true });\n    const raw = await fs.readFile(this.filePath, 'utf8').catch(() => '');\n    if (!raw.trim()) return;\n    const parsed = JSON.parse(raw) as MemoryItem[];\n    this.items = new Map(parsed.map((item) => [item.key, item]));\n  }\n\n  private async saveFile() {\n    await fs.mkdir(path.dirname(this.filePath), { recursive: true });\n    await fs.writeFile(this.filePath, JSON.stringify([...this.items.values()], null, 2), 'utf8');\n  }\n\n  async put(key: string, value: unknown, tags: string[] = []) {\n    const now = new Date().toISOString();\n    const existing = this.items.get(key);\n    const item: MemoryItem = {\n      id: existing?.id ?? crypto.randomUUID(),\n      key,\n      value,\n      tags,\n      createdAt: existing?.createdAt ?? now,\n      updatedAt: now,\n    };\n    this.items.set(key, item);\n    await this.saveFile();\n    return item;\n  }\n\n  get(key: string) {\n    return this.items.get(key) ?? null;\n  }\n\n  list(prefix = '') {\n    return [...this.items.values()].filter((item) => item.key.startsWith(prefix)).sort((a, b) => a.key.localeCompare(b.key));\n  }\n\n  async remove(key: string) {\n    const ok = this.items.delete(key);\n    await this.saveFile();\n    return { ok };\n  }\n\n  async clear() {\n    this.items.clear();\n    await this.saveFile();\n    return { ok: true };\n  }\n}\n",
  "src/runtime.ts": "import { config } from './config.js';\nimport { BrowserPool } from './browser/pool.js';\nimport { FileService } from './files/service.js';\nimport { MemoryStore } from './memory/store.js';\n\nexport function createRuntime() {\n  const browser = new BrowserPool(\n    { profileRoot: config.profileRoot, downloadRoot: config.downloadRoot },\n    'default'\n  );\n  const files = new FileService(config.allowedFileRoots);\n  const memory = new MemoryStore(`${config.stateDir}/memory.json`);\n  return { browser, files, memory, config };\n}\n",
  "src/safety/allowlist.ts": "export function isAllowedUrl(url: string, allowedOrigins: string[]) {\n  if (!allowedOrigins.length) return true;\n  try {\n    const origin = new URL(url).origin;\n    return allowedOrigins.includes(origin);\n  } catch {\n    return false;\n  }\n}\n",
  "src/safety/confirm.ts": "export async function confirmAction(message: string) {\n  return { confirmed: true, message };\n}\n",
  "src/safety/permissions.ts": "export type Permission = 'read' | 'write' | 'risky';\n",
  "src/safety/policy.ts": "import { AppError } from '../errors.js';\n\nfunction isPrivateHost(hostname: string) {\n  const host = hostname.toLowerCase();\n  if (['localhost', '::1'].includes(host)) return true;\n  if (host.endsWith('.local')) return true;\n  if (/^127\\./.test(host)) return true;\n  if (/^10\\./.test(host)) return true;\n  if (/^192\\.168\\./.test(host)) return true;\n  const match = host.match(/^172\\.(\\d+)\\./);\n  if (match) {\n    const n = Number(match[1]);\n    if (n >= 16 && n <= 31) return true;\n  }\n  return false;\n}\n\nexport function validateUrl(input: string) {\n  let url: URL;\n  try {\n    url = new URL(input);\n  } catch {\n    throw new AppError(`Invalid URL: ${input}`, 'INVALID_URL');\n  }\n\n  if (!['http:', 'https:'].includes(url.protocol)) {\n    throw new AppError(`Blocked URL protocol: ${url.protocol}`, 'BLOCKED_PROTOCOL');\n  }\n\n  return url;\n}\n\nexport function assertAllowedNavigation(input: string, allowedOrigins: string[], deniedHosts: string[]) {\n  const url = validateUrl(input);\n  const host = url.hostname.toLowerCase();\n\n  if (deniedHosts.map((h) => h.toLowerCase()).includes(host) || isPrivateHost(host)) {\n    throw new AppError(`Blocked host: ${host}`, 'BLOCKED_HOST');\n  }\n\n  if (allowedOrigins.length > 0 && !allowedOrigins.includes(url.origin)) {\n    throw new AppError(`Origin not allowed: ${url.origin}`, 'ORIGIN_NOT_ALLOWED');\n  }\n\n  return url;\n}\n",
  "src/server.ts": "import { Server } from '@modelcontextprotocol/sdk/server/index.js';\nimport { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';\nimport { CallToolRequestSchema, ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js';\nimport { config } from './config.js';\nimport { logger } from './logger.js';\nimport { toolDefinitions } from './mcp/tool-definitions.js';\nimport { AppError } from './errors.js';\nimport { createRuntime } from './runtime.js';\n\nfunction safeText(data: unknown) {\n  if (typeof data === 'string') return data;\n  try { return JSON.stringify(data, null, 2); } catch { return String(data); }\n}\n\nfunction textResult(data: unknown) {\n  return { content: [{ type: 'text' as const, text: safeText(data) }] };\n}\n\nfunction imageResult(base64Png: string) {\n  return { content: [{ type: 'image' as const, data: base64Png, mimeType: 'image/png' as const }] };\n}\n\nfunction parseMaybeJson<T = unknown>(value: string) {\n  return JSON.parse(value) as T;\n}\n\nconst confirmRequired = new Set([\n  'browser.click', 'browser.type', 'browser.press', 'browser.select', 'browser.check', 'browser.uncheck',\n  'browser.submit', 'browser.hover', 'browser.scroll', 'browser.drag_drop', 'browser.upload_files',\n  'browser.upload_folder', 'browser.set_cookie', 'browser.import_cookies', 'browser.export_cookies',\n  'browser.clear_cookies', 'browser.clear_storage', 'browser.set_viewport', 'browser.evaluate',\n  'browser.close_tab', 'browser.close_others',\n  'files.write_text', 'files.write_binary', 'files.write_bundle', 'files.touch', 'files.mkdir',\n  'files.copy', 'files.move', 'files.delete', 'files.zip', 'files.unzip',\n  'memory.put', 'memory.delete', 'memory.clear',\n]);\n\nexport async function createMcpServer(runtime = createRuntime()) {\n  const { browser, files, memory } = runtime;\n  await memory.load().catch(() => undefined);\n  const server = new Server({ name: config.appName, version: config.version }, { capabilities: { tools: {} } });\n\n  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: toolDefinitions as any }));\n\n  server.setRequestHandler(CallToolRequestSchema, async (request) => {\n    const args = (request.params.arguments ?? {}) as Record<string, unknown>;\n\n    try {\n      if (confirmRequired.has(request.params.name) && args.confirm !== true) {\n        throw new AppError(`Confirmation required for ${request.params.name}`, 'CONFIRM_REQUIRED');\n      }\n      switch (request.params.name) {\n        case 'browser.list_profiles':\n          return textResult(await browser.listProfiles());\n        case 'browser.create_profile':\n          return textResult(await browser.createProfile(String(args.profileId ?? 'default')));\n        case 'browser.use_profile':\n          return textResult(await browser.useProfile(String(args.profileId ?? 'default')));\n        case 'browser.current_profile':\n          return textResult({ profileId: browser.getActiveProfileId() });\n        case 'browser.current_page':\n          return textResult(await browser.currentPage());\n        case 'browser.close_profile':\n          return textResult(await browser.closeProfile(String(args.profileId ?? 'default')));\n        case 'browser.close_all_profiles':\n          return textResult(await browser.closeAllProfiles());\n        case 'browser.request_rules':\n          return textResult(await browser.getRequestRules());\n        case 'browser.set_request_rules':\n          return textResult(await browser.setRequestRules({\n            blockedDomains: Array.isArray(args.blockedDomains) ? args.blockedDomains.map(String) : undefined,\n            blockedResourceTypes: Array.isArray(args.blockedResourceTypes) ? args.blockedResourceTypes.map(String) : undefined,\n          }));\n        case 'browser.clear_request_rules':\n          return textResult(await browser.clearRequestRules());\n        case 'browser.navigate':\n          return textResult(await browser.navigate(String(args.url ?? ''), config.allowedOrigins, config.deniedHosts));\n        case 'browser.open_tab':\n          return textResult(await browser.openTab(args.url ? String(args.url) : undefined, config.allowedOrigins, config.deniedHosts));\n        case 'browser.close_tab':\n          return textResult(await browser.closeTab());\n        case 'browser.close_others':\n          return textResult(await browser.closeOthers());\n        case 'browser.back':\n          return textResult(await browser.back());\n        case 'browser.forward':\n          return textResult(await browser.forward());\n        case 'browser.reload':\n          return textResult(await browser.reload());\n        case 'browser.snapshot':\n          return textResult(await browser.snapshot());\n        case 'browser.click':\n          return textResult(await browser.click({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined }));\n        case 'browser.type':\n          return textResult(await browser.type({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, text: String(args.text ?? '') }));\n        case 'browser.press':\n          return textResult(await browser.press({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, key: String(args.key ?? '') }));\n        case 'browser.select':\n          return textResult(await browser.select({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, value: args.value ? String(args.value) : undefined, values: Array.isArray(args.values) ? args.values.map(String) : undefined }));\n        case 'browser.check':\n          return textResult(await browser.check({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined }));\n        case 'browser.uncheck':\n          return textResult(await browser.uncheck({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined }));\n        case 'browser.submit':\n          return textResult(await browser.submit({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined }));\n        case 'browser.hover':\n          return textResult(await browser.hover({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined }));\n        case 'browser.scroll':\n          return textResult(await browser.scroll({ selector: args.selector ? String(args.selector) : undefined, dx: typeof args.dx === 'number' ? args.dx : undefined, dy: typeof args.dy === 'number' ? args.dy : undefined }));\n        case 'browser.drag_drop':\n          return textResult(await browser.dragDrop({ sourceRef: args.sourceRef ? String(args.sourceRef) : undefined, sourceSelector: args.sourceSelector ? String(args.sourceSelector) : undefined, targetRef: args.targetRef ? String(args.targetRef) : undefined, targetSelector: args.targetSelector ? String(args.targetSelector) : undefined }));\n        case 'browser.upload_files': {\n          const filesArg = Array.isArray(args.files) ? args.files.map(String) : [];\n          if (!filesArg.length) throw new AppError('No files provided', 'MISSING_FILES');\n          for (const file of filesArg) await files.stat(file);\n          return textResult(await browser.uploadFiles({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, files: filesArg }));\n        }\n        case 'browser.upload_folder': {\n          const fileList = await files.collectFiles(String(args.path ?? ''), args.recursive !== false);\n          if (!fileList.length) throw new AppError('No files found in folder', 'MISSING_FILES');\n          for (const file of fileList) await files.stat(file);\n          return textResult(await browser.uploadFiles({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, files: fileList }));\n        }\n        case 'browser.set_cookie':\n          return textResult(await browser.setCookie(Array.isArray(args.cookies) ? (args.cookies as any[]) : []));\n        case 'browser.import_cookies': {\n          let cookies = args.cookies as any[] | undefined;\n          if (!cookies && typeof args.path === 'string' && args.path) {\n            const raw = await files.readText(String(args.path));\n            const parsed = parseMaybeJson<any>(raw);\n            cookies = Array.isArray(parsed) ? parsed : Array.isArray(parsed.cookies) ? parsed.cookies : [];\n          }\n          return textResult(await browser.importCookies((cookies ?? []) as any[]));\n        }\n        case 'browser.export_cookies': {\n          const cookies = await browser.exportCookies();\n          const payload = JSON.stringify({ cookies }, null, 2);\n          if (typeof args.path === 'string' && args.path) {\n            await files.writeText(String(args.path), payload);\n            return textResult({ ok: true, count: cookies.length, path: String(args.path) });\n          }\n          return textResult({ cookies });\n        }\n        case 'browser.clear_cookies':\n          return textResult(await browser.clearCookies());\n        case 'browser.clear_storage':\n          return textResult(await browser.clearStorage());\n        case 'browser.set_viewport':\n          return textResult(await browser.setViewport(Number(args.width), Number(args.height)));\n        case 'browser.evaluate':\n          return textResult(await browser.evaluate(String(args.code ?? '')));\n        case 'browser.downloads_list':\n          return textResult(await browser.listDownloads());\n        case 'browser.extract':\n          return textResult(await browser.extract({ ref: args.ref ? String(args.ref) : undefined, selector: args.selector ? String(args.selector) : undefined, attribute: args.attribute ? String(args.attribute) : undefined }));\n        case 'browser.wait':\n          return textResult(await browser.wait({ ms: typeof args.ms === 'number' ? args.ms : undefined, selector: args.selector ? String(args.selector) : undefined, state: args.state === 'attached' || args.state === 'detached' || args.state === 'visible' || args.state === 'hidden' ? args.state : undefined }));\n        case 'browser.screenshot':\n          return imageResult(await browser.screenshot());\n        case 'files.list':\n          return textResult(await files.list(String(args.path ?? '')));\n        case 'files.tree':\n          return textResult(await files.tree(String(args.path ?? ''), typeof args.depth === 'number' ? args.depth : undefined, typeof args.maxEntries === 'number' ? args.maxEntries : undefined));\n        case 'files.read_text':\n          return textResult(await files.readText(String(args.path ?? '')));\n        case 'files.read_binary':\n          return textResult(await files.readBinary(String(args.path ?? '')));\n        case 'files.write_text':\n          return textResult(await files.writeText(String(args.path ?? ''), String(args.content ?? '')));\n        case 'files.write_binary':\n          return textResult(await files.writeBinary(String(args.path ?? ''), String(args.base64 ?? '')));\n        case 'files.write_bundle':\n          return textResult(await files.writeBundle(Array.isArray(args.entries) ? args.entries as any[] : []));\n        case 'files.touch':\n          return textResult(await files.touch(String(args.path ?? '')));\n        case 'files.mkdir':\n          return textResult(await files.mkdir(String(args.path ?? '')));\n        case 'files.stat':\n          return textResult(await files.stat(String(args.path ?? '')));\n        case 'files.preview':\n          return textResult(await files.preview(String(args.path ?? '')));\n        case 'files.copy':\n          return textResult(await files.copy(String(args.source ?? ''), String(args.destination ?? '')));\n        case 'files.move':\n          return textResult(await files.move(String(args.source ?? ''), String(args.destination ?? '')));\n        case 'files.delete':\n          return textResult(await files.remove(String(args.path ?? '')));\n        case 'files.zip':\n          return textResult(await files.zip(Array.isArray(args.sources) ? args.sources.map(String) : [], String(args.destination ?? '')));\n        case 'files.unzip':\n          return textResult(await files.unzip(String(args.source ?? ''), String(args.destination ?? '')));\n        case 'memory.put':\n          return textResult(await memory.put(String(args.key ?? ''), args.value, Array.isArray(args.tags) ? args.tags.map(String) : []));\n        case 'memory.get':\n          return textResult(await memory.get(String(args.key ?? '')));\n        case 'memory.list':\n          return textResult(await memory.list(String(args.prefix ?? '')));\n        case 'memory.delete':\n          return textResult(await memory.remove(String(args.key ?? '')));\n        case 'memory.clear':\n          return textResult(await memory.clear());\n        default:\n          throw new AppError(`Unknown tool: ${request.params.name}`, 'UNKNOWN_TOOL');\n      }\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error);\n      logger.warn('tool-error', request.params.name, message);\n      return { content: [{ type: 'text', text: JSON.stringify({ ok: false, error: message }, null, 2) }], isError: true };\n    }\n  });\n\n  return { server, runtime };\n}\n\nexport async function startStdioServer() {\n  const { server, runtime } = await createMcpServer();\n  const transport = new StdioServerTransport();\n  await server.connect(transport);\n  return { close: async () => { await runtime.browser.close(); } };\n}\n",
  "tools/file-browser.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>MCP File Browser</title>\n  <style>\n    body { font-family: system-ui, sans-serif; margin: 16px; }\n    .row { display: flex; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }\n    input, textarea, button { font: inherit; }\n    input, textarea { width: 100%; box-sizing: border-box; }\n    textarea { min-height: 100px; }\n    #tree, #log { white-space: pre-wrap; background: #f6f6f6; padding: 12px; border-radius: 8px; }\n    .panel { margin: 12px 0; padding: 12px; border: 1px solid #ddd; border-radius: 10px; }\n    .small { font-size: 12px; color: #555; }\n  </style>\n</head>\n<body>\n  <h1>MCP File Browser</h1>\n  <p class=\"small\">Browse files in /workspace or /mnt, create folders, and create files.</p>\n\n  <div class=\"panel\">\n    <div class=\"row\">\n      <input id=\"path\" value=\"/workspace\" />\n      <button onclick=\"refreshTree()\">Refresh</button>\n    </div>\n    <div id=\"tree\"></div>\n  </div>\n\n  <div class=\"panel\">\n    <h3>Create folder</h3>\n    <div class=\"row\"><input id=\"mkdirPath\" placeholder=\"/workspace/new-folder\" /></div>\n    <div class=\"row\"><button onclick=\"createFolder()\">Create folder</button></div>\n  </div>\n\n  <div class=\"panel\">\n    <h3>Create file</h3>\n    <div class=\"row\"><input id=\"filePath\" placeholder=\"/workspace/new-folder/file.txt\" /></div>\n    <div class=\"row\"><textarea id=\"fileContent\" placeholder=\"file contents\"></textarea></div>\n    <div class=\"row\"><button onclick=\"createFile()\">Create file</button></div>\n  </div>\n\n  <div class=\"panel\">\n    <h3>Log</h3>\n    <div id=\"log\"></div>\n  </div>\n\n  <script>\n    const log = (msg) => document.getElementById('log').textContent = msg;\n    const joinPath = (base, child) => base.replace(/\\/+$/, '') + '/' + child.replace(/^\\/+/, '');\n\n    async function refreshTree() {\n      const base = document.getElementById('path').value.trim();\n      const entries = await listFiles(base);\n      const out = [];\n      for (const entry of entries) {\n        const info = await stat(joinPath(base, entry));\n        out.push((info.type === 'directory' ? '📁 ' : '📄 ') + entry);\n      }\n      document.getElementById('tree').textContent = out.join('\\n') || '(empty)';\n      log('Loaded ' + entries.length + ' entries');\n    }\n\n    async function createFolder() {\n      const p = document.getElementById('mkdirPath').value.trim();\n      await mkdir(p);\n      log('Created folder: ' + p);\n      refreshTree();\n    }\n\n    async function createFile() {\n      const p = document.getElementById('filePath').value.trim();\n      const content = document.getElementById('fileContent').value;\n      await writeFile(p, content);\n      log('Created file: ' + p);\n      refreshTree();\n    }\n\n    refreshTree().catch(err => log(String(err)));\n  </script>\n</body>\n</html>",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"NodeNext\",\n    \"moduleResolution\": \"NodeNext\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"skipLibCheck\": true,\n    \"outDir\": \"dist\",\n    \"rootDir\": \"src\",\n    \"types\": [\"node\"]\n  },\n  \"include\": [\"src/**/*.ts\"],\n  \"exclude\": [\"dist\", \"node_modules\"]\n}\n"
};

for (const [rel, content] of Object.entries(files)) {
  const filePath = path.resolve(process.cwd(), rel);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content, 'utf8');
}

console.log('Wrote', Object.keys(files).length, 'files');
